{"security_risk": "LOW", "summary": "Parse silence.log into intervals and print longest pauses", "command": "python3 - <<'PY'
import re
starts=[]
intervals=[]
cur=None
for line in open('silence.log', 'r', errors='ignore'):
    m=re.search(r'silence_start: ([0-9.]+)', line)
    if m:
        cur=float(m.group(1))
        continue
    m=re.search(r'silence_end: ([0-9.]+) \| silence_duration: ([0-9.]+)', line)
    if m and cur is not None:
        end=float(m.group(1)); dur=float(m.group(2))
        intervals.append((cur,end,dur))
        cur=None

intervals.sort(key=lambda x:x[2], reverse=True)
print('count',len(intervals))
for s,e,d in intervals[:20]:
    print(f'{s:.3f} {e:.3f} {d:.3f}')
PY"}

{"security_risk": "LOW", "summary": "Check earliest and latest detected silence intervals in log", "command": "python3 - <<'PY'
import re
cur=None
intervals=[]
for line in open('silence.log','r',errors='ignore'):
    m=re.search(r'silence_start: ([0-9.]+)', line)
    if m:
        cur=float(m.group(1));
    m=re.search(r'silence_end: ([0-9.]+) \| silence_duration: ([0-9.]+)', line)
    if m and cur is not None:
        intervals.append((cur,float(m.group(1)),float(m.group(2))))
        cur=None
print('min_start',min(i[0] for i in intervals), 'max_end',max(i[1] for i in intervals))
# print first 5 by time
intervals.sort()
for s,e,d in intervals[:10]:
    print(f'{s:.3f} {e:.3f} {d:.3f}')
PY"}

